import os, re
from pypdf import PdfReader
reader = PdfReader(os.environ['PDF_PATH'])
for i, page in enumerate(reader.pages, start=1):
    text = page.extract_text() or ''
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    hits = []
    for ln in lines:
        if re.match(r'^(\d+\.|[一二三四五六七八九十]+[、.．]|第[一二三四五六七八九十0-9]+|Skill|场景|建议|结论|核心|下一步|MCP|AGENTS|\.agents|ai-design-kit)', ln):
            hits.append(ln)
    if hits:
        print(f'--- PAGE {i} ---')
        for h in hits[:12]:
            print(h[:180])
