{"command":"$env:PYTHONIOENCODING='utf-8'
@'
import json, re, sys
from pathlib import Path
root=Path(r'C:\Users\jovi\OneDrive\文档\ai design kit')
errors=[]
for skill in sorted((root/'.agents'/'skills').iterdir()):
    if not skill.is_dir():
        continue
    p=skill/'SKILL.md'
    text=p.read_text(encoding='utf-8')
    if not text.startswith('---\n'):
        errors.append(f'{p}: missing frontmatter')
        continue
    end=text.find('\n---\n',4)
    if end<0:
        errors.append(f'{p}: unclosed frontmatter')
        continue
    fm=text[4:end]
    fields={}
    for line in fm.splitlines():
        if ':' in line:
            k,v=line.split(':',1)
            fields[k.strip()]=v.strip().strip('"')
    name=fields.get('name')
    desc=fields.get('description')
    if name != skill.name:
        errors.append(f'{p}: name {name!r} != folder {skill.name!r}')
    if not name or not re.match(r'^[a-z0-9-]+$', name):
        errors.append(f'{p}: invalid name {name!r}')
    if not desc or len(desc) < 40 or 'TODO' in desc:
        errors.append(f'{p}: weak description')
    if 'TODO' in text or '[TODO' in text:
        errors.append(f'{p}: TODO remains')
for schema in sorted((root/'ai-design-kit'/'schemas').glob('*.json')):
    try:
        json.loads(schema.read_text(encoding='utf-8'))
    except Exception as e:
        errors.append(f'{schema}: invalid JSON {e}')
if errors:
    print('\n'.join(errors))
    sys.exit(1)
print('ok skills', len(list((root/'.agents'/'skills').iterdir())))
print('ok schemas', len(list((root/'ai-design-kit'/'schemas').glob('*.json'))))
