 'Layout':['Do not use for small local component alignment; use Flex, Grid, or Space instead.'],
 'Menu':['Do not use for simple inline action lists; use buttons, tabs, or dropdowns as appropriate.'],
 'Typography':['Do not create arbitrary text styles outside tokenized typography rules.'],
 'Form':['Do not use for read-only field display; use descriptions or data display components.'],
 'Input':['Do not use when the value should be chosen from constrained options; use Select, Radio, Checkbox, DatePicker, etc.'],
