 'Space':['Do not use as a semantic layout replacement for page structure.'],
 'Flex':['Do not use to bypass component slot rules or page layout recipes.'],
 'Grid':['Do not use for minor inline spacing; use Space or Flex.']
}
variant_prop_names={'type','variant','size','shape','color','mode','layout','align','justify','direction','wrap'}
component_category={}
try:
    list_data=json.loads((cli/'components.list.json').read_text(encoding='utf-8-sig'))
    for item in list_data:
        component_category[item['name']]=item.get('category')
except Exception:
    list_data=[]

def load_json(path):
    txt=path.read_text(encoding='utf-8-sig')
    try: return json.loads(txt)
    except Exception: return {'raw':txt}

def extract_when(md):
    if not md: return ''
    m=re.search(r'## When To Use\s+(.+?)(?:\n## |\n### |\Z)', md, flags=re.S)
    if not m: return ''
    text=re.sub(r'```.*?```','',m.group(1), flags=re.S)
    text=re.sub(r'\n+', ' ', text).strip()
    return text[:800]

def contract_for(c):
    info=load_json(cli/f'{c}.info.json')
    semantic=load_json(cli/f'{c}.semantic.json') if (cli/f'{c}.semantic.json').exists() else {}
    props={}
    variants={}
    for p in info.get('props',[]) or []:
        name=p.get('name')
        if not name: continue
        prop={'type':p.get('type','unknown') or 'unknown'}
        if p.get('default') not in (None,''):
            prop['default']=p.get('default')
        if p.get('since') not in (None,''):
            prop['since']=p.get('since')
        if name in variant_prop_names or ('`' in prop['type'] and '|' in prop['type']):
            vals=re.findall(r'`([^`]+)`', prop['type'])
            if vals:
                variants[name]={'values':vals,'source':'antd-cli-info'}
        props[name]=prop
