      'code':{'framework':'react','import':'antd','component':c,'propMap':{k:k for k in props.keys()},'needsReview':False},
      'examples':{'good':[{'source':f'ant-design-docs:{c}','summary':extract_when((raw/(c.lower() if c!='Layout' else 'layout-component')).with_suffix('.md').read_text(encoding='utf-8', errors='ignore') if (raw/(c.lower() if c!='Layout' else 'layout-component')).with_suffix('.md').exists() else '') or info.get('description','')}], 'bad':[]},
