@'
import json, os, subprocess, sys, time
from pathlib import Path
from concurrent.futures import ThreadPoolExecutor, as_completed

root = Path.cwd()
base = root / 'ai-design-kit/sources/cli/ant-design'
base.mkdir(parents=True, exist_ok=True)
bin_path = os.environ['ANTD_BIN']
components = json.loads((base / 'components.list.json').read_text(encoding='utf-8-sig'))
commands = ['info', 'semantic', 'token', 'doc']

results = []

def run_one(component, command):
    name = component['name']
    ext = 'md' if command == 'doc' else 'json'
    out_path = base / f'{name}.{command}.{ext}'
    args = [bin_path, '--version', '6.4.3', command, name]
    if command != 'doc':
        args += ['--format', 'json']
    else:
        args += ['--format', 'markdown']
    started = time.time()
    try:
        proc = subprocess.run(args, cwd=root, text=True, encoding='utf-8', errors='replace', stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=40)
        stdout = proc.stdout.strip()
        stderr = proc.stderr.strip()
        if command != 'doc':
            try:
                data = json.loads(stdout)
            except Exception:
                data = {
                    'name': name,
                    'command': command,
                    'status': 'not_available' if 'No ' in stdout or 'not available' in stdout.lower() else 'non_json_output',
                    'message': stdout,
                    'stderr': stderr,
                    'exitCode': proc.returncode,
                    'source': '@ant-design/cli'
                }
            out_path.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding='utf-8')
        else:
            out_path.write_text(stdout + ('\n' if stdout else ''), encoding='utf-8')
        return {'component': name, 'command': command, 'ok': proc.returncode == 0, 'exitCode': proc.returncode, 'seconds': round(time.time()-started, 3), 'stderr': stderr[:300]}
    except Exception as e:
        out_path.write_text(json.dumps({'name': name, 'command': command, 'status': 'error', 'error': repr(e), 'source': '@ant-design/cli'}, ensure_ascii=False, indent=2), encoding='utf-8')
        return {'component': name, 'command': command, 'ok': False, 'error': repr(e), 'seconds': round(time.time()-started, 3)}

jobs = []
with ThreadPoolExecutor(max_workers=8) as ex:
    for c in components:
        for cmd in commands:
            jobs.append(ex.submit(run_one, c, cmd))
    for fut in as_completed(jobs):
        r = fut.result()
        results.append(r)
        if not r.get('ok'):
            print('WARN', r)

summary = {
    'componentCount': len(components),
    'commandCount': len(results),
    'failed': [r for r in results if not r.get('ok')],
    'generatedAt': '2026-06-12T00:00:00+08:00'
}
(base / 'full-cli-fetch.summary.json').write_text(json.dumps(summary, ensure_ascii=False, indent=2), encoding='utf-8')
print('components', len(components), 'commands', len(results), 'failed', len(summary['failed']))
