import json
from pathlib import Path
from jsonschema import Draft202012Validator
root = Path.cwd()
adk = root / 'ai-design-kit'
checks = []

def load(path):
    return json.loads(path.read_text(encoding='utf-8'))

def validate(schema_path, data_path):
    schema = load(schema_path)
    data = load(data_path)
    validator = Draft202012Validator(schema)
    errors = sorted(validator.iter_errors(data), key=lambda e: e.path)
    checks.append((str(data_path.relative_to(root)), len(errors), [e.message for e in errors[:5]]))

validate(adk / 'schemas' / 'coverage-manifest.schema.json', adk / 'coverage' / 'untitled-ui-public-test.coverage.json')
validate(adk / 'schemas' / 'semantic-ops.schema.json', adk / 'semantic' / 'generated' / 'relayops-homepage.ops.json')
validate(adk / 'schemas' / 'token-graph.schema.json', adk / 'tokens' / 'untitled-ui-public-token-graph.json')
for path in sorted((adk / 'components').glob('untitled-ui.*.contract.json')):
    validate(adk / 'schemas' / 'component-contract.schema.json', path)

plan = load(adk / 'semantic' / 'generated' / 'relayops-homepage.plan.json')
graph = load(adk / 'semantic' / 'generated' / 'relayops-homepage.graph.json')
ops = load(adk / 'semantic' / 'generated' / 'relayops-homepage.ops.json')
contracts = {p.stem.replace('.contract','') for p in (adk / 'components').glob('untitled-ui.*.contract.json')}
custom_errors = []
node_ids = set(graph['nodes'])
for section in plan['sections']:
    if section['id'] not in node_ids:
        custom_errors.append(f"plan section missing in graph: {section['id']}")
for node_id, node in graph['nodes'].items():
    for child in node.get('children', []):
        if child not in node_ids:
            custom_errors.append(f"graph child missing: {node_id}->{child}")
    cid = node.get('componentId')
    if cid and cid not in contracts:
        custom_errors.append(f"component contract missing: {node_id} {cid}")
    if cid == 'untitled-ui.header-navigation':
        custom_errors.append('HeaderNavigationBase should not be used in RelayOps graph')
for op in ops['operations']:
    if op.get('op') == 'component.insert' and op.get('componentId'):
        refs = op.get('contractRefs', [])
        if op['componentId'] not in refs:
            custom_errors.append(f"op missing contractRefs for {op.get('node',{}).get('id')}")

for path, count, errors in checks:
    status = 'PASS' if count == 0 else 'FAIL'
    print(f'{status} {path} errors={count}')
    for err in errors:
        print(f'  - {err}')
if custom_errors:
    print('FAIL custom consistency errors=%d' % len(custom_errors))
    for err in custom_errors[:20]:
        print('  -', err)
else:
    print('PASS custom consistency errors=0')
if any(count for _, count, _ in checks) or custom_errors:
    raise SystemExit(1)
print(f'validated={len(checks)} schema files + custom consistency')
