{"command":"@'
import json
from pathlib import Path
from jsonschema import Draft202012Validator
root=Path.cwd(); adk=root/'ai-design-kit'; slug='aigateway-antd-admin-console'
selected=['layout','menu','breadcrumb','tabs','flex','space','typography','card','statistic','table','tag','badge','progress','alert','form','input','select','date-picker','switch','button','descriptions','timeline','drawer','modal','divider']
def load(p): return json.loads(p.read_text(encoding='utf-8'))
checks=[]
def validate(schema,data):
    errors=sorted(Draft202012Validator(load(schema)).iter_errors(load(data)), key=lambda e:e.path)
    checks.append((str(data.relative_to(root)),len(errors),[e.message for e in errors[:3]]))
validate(adk/'schemas'/'coverage-manifest.schema.json', adk/'coverage'/f'{slug}.coverage.json')
validate(adk/'schemas'/'semantic-ops.schema.json', adk/'semantic'/'generated'/f'{slug}.ops.json')
for cid in selected:
    validate(adk/'schemas'/'component-contract.schema.json', adk/'components'/f'antd.{cid}.contract.json')
for p in [adk/'reports'/'validation'/f'{slug}.json', adk/'semantic'/'generated'/f'{slug}.repair-ops.json', adk/f'kit.{slug}.json']:
    load(p); checks.append((str(p.relative_to(root)),0,[]))
ops=load(adk/'semantic'/'generated'/f'{slug}.ops.json'); graph=load(adk/'semantic'/'generated'/f'{slug}.graph.json')
contracts={p.stem.replace('.contract','') for p in (adk/'components').glob('antd.*.contract.json')}
custom=[]
for nid,node in graph['nodes'].items():
    cid=node.get('componentId')
    if cid and cid not in contracts: custom.append(f'missing contract {nid}:{cid}')
    for child in node.get('children',[]):
        if child not in graph['nodes']: custom.append(f'missing child {nid}->{child}')
for op in ops['operations']:
    if op.get('op')=='component.insert' and op.get('componentId') and op['componentId'] not in op.get('contractRefs',[]):
        custom.append(f'op missing contractRefs {op.get("node",{}).get("id")}')
for path,count,errs in checks:
    print(('PASS' if count==0 else 'FAIL'), path, 'errors='+str(count))
    for err in errs: print('  -',err)
print(('PASS' if not custom else 'FAIL'), 'custom graph/contract consistency errors='+str(len(custom)))
print('export exists=', (adk/'pencil'/'exports'/'Jm0RK.png').exists())
if any(c for _,c,_ in checks) or custom or not (adk/'pencil'/'exports'/'Jm0RK.png').exists(): raise SystemExit(1)
